  // Help centre and live demo

  'demo.bar.tag': 'تجريبي',
  'demo.bar.opening': 'جارٍ فتح العرض التجريبي لـ Curahold',
  'demo.bar.step.db': 'تشغيل Postgres في هذا التبويب. لا تغادر أي بيانات متصفحك.',
  'demo.bar.step.schema': 'إنشاء الجداول وقواعد الوصول.',
  'demo.bar.step.data': 'تحميل محفظة عملاء متخيَّلة.',
  'demo.bar.step.app': 'فتح التطبيق.',
  'demo.bar.failed': 'تعذّر تشغيل العرض التجريبي. أعد تحميل الصفحة وحاول مرة أخرى.',
  'demo.bar.still': 'ما زال التحضير جاريًا. يستغرق التشغيل الأول وقتًا أطول قليلًا على الأجهزة الأبطأ.',
  'demo.bar.stuck': 'تعذّر تسجيل دخولك إلى العرض التجريبي.',
  'demo.bar.note': 'بيانات متخيَّلة تعمل بالكامل في هذا التبويب. إعادة التحميل تبدأ من جديد.',
  'demo.bar.as': 'تعرض بصفة',
  'demo.bar.language': 'لغة العرض التجريبي',
  'demo.bar.tries': 'ماذا تجرّب؟',
  'demo.bar.tours': 'كل الجولات',
  'demo.bar.reset': 'ابدأ من جديد',
  'demo.bar.customer': 'عميل · بوابة {company}',
  'demo.idea.1': 'اضغط N واكتب: «مكالمة تجديد مع Acme friday @نور #فيلتو !high». يُملأ التاريخ والشخص والعميل والأولوية تلقائيًا، وإذا لصقت عدة أسطر يصبح كل سطر مهمة مستقلة.',
  'demo.idea.2': 'في «مهامي» انقر الدائرة أمام أي مهمة فتكتمل. تراجع عنها من الإشعار في الأسفل.',
  'demo.idea.3': 'العملاء ← كل العملاء: عرض «بطاقات» يبيّن من يحتاج إلى اهتمام ولماذا. جرّب أيضًا عرضَي «التجديدات» و«المنتجات».',
  'demo.idea.4': 'العملاء ← الفرص: اسحب صفقة إلى مرحلة أخرى أو أفلتها على «تم الفوز»، فيتغيّر التوقع في الأعلى فورًا.',
  'demo.idea.5': 'الرؤى ← التقارير: أنشئ تقريرك بزر «تقرير جديد» أو افتح تقريرًا جاهزًا وعدّله. الرؤى ← لوحات المعلومات: زر «إضافة» يضع لوحة جاهزة في صفحتك الرئيسية.',
  'demo.idea.6': 'الرؤى ← الفريق: من يحمل ماذا، وما المتأخر، وعرض لاجتماع ثنائي مع كل شخص. العمل ← المخطط الزمني يعرض الأسابيع القادمة.',
  'demo.idea.7': 'العملاء ← مراجعات الأعمال: من تأخرت مراجعته أو اقتربت. زر «تم» يسجّل مراجعة وينقل الموعد التالي. يُضبط الإيقاع في الإعدادات ← الأهداف والإيقاع.',
  'demo.idea.8': 'افتح مهمة في لوحة «نجاح العملاء — عام»: متابعة، ربط مهمة («تنتظر»)، الوقت المستغرق، قائمة التحقق، والسجل في الأسفل. جرّب «تصفية» و«العروض» في اللوحة.',
  'demo.idea.9': 'في صفحة أي عميل، يضيف زر «تطبيق كتيب عمل» مهام الإعداد بنقرة واحدة.',
  'demo.idea.10': 'احذف مهمة أو عميلًا، ثم اختر «تراجع» من الإشعار في الأسفل، أو افتح سلة المحذوفات من قائمتك. ما تحذفه يبقى 30 يومًا ويعود بكل ما تحته.',
  'demo.idea.11': 'CuraAI في أسفل اليسار: اسأل بكلماتك (مثلًا «كيف أستورد العملاء؟»). تأتي الإجابة من الوثائق مع مصدرها.',
  'demo.idea.12': 'الإعدادات ← أنظمة إدارة العملاء وجداول البيانات: اربط نظام CRM. نظام تجريبي ببيانات مختلَقة يمرّ بالخطوات الحقيقية: السماح، اختيار ما يُنقل، مطابقة الحقول، ثم أول مزامنة.',
  'demo.idea.13': 'افتح عميلًا (فيلتو للتنقل مثلًا): سجّل مكالمة في مخططه الزمني وانظر إلى «لماذا؟» بجانب مؤشر الصحة.',
  'demo.idea.14': 'الإعدادات ← مؤشر الصحة: غيّر الأوزان، وتعرض المعاينة درجة كل عميل فورًا.',
  'demo.idea.15': 'Ctrl K (أو ⌘ K على Mac) يجد أي عميل أو مهمة أو شخص أو إعداد.',
  'demo.idea.16': 'حدّد عدة مهام في لوحة، وغيّرها معًا، ثم تراجع.',
  'demo.idea.17': 'الإعدادات ← الأدوار والصلاحيات: «عرضه كما يراه …» يُريك الشاشات بعيني أحد الأعضاء.',
  'demo.idea.18': 'انتقل في الأعلى إلى نور الهاشمي أو دانة القحطاني وانظر ما الذي يتغيّر في الشاشات نفسها.',
  'demo.idea.19': 'انتقل في الأعلى إلى ليان السعدي (عميلة): في بوابة كويلفيلد ترى فقط ما شوركت فيه. افتح طلبًا واكتب ردًا، ثم افتحه بصفتك نور في لوحة «نجاح العملاء — عام» واختر «رد على العميل».',
  'demo.idea.20': 'قائمتك في أسفل اليسار: «المظهر» للوضع الداكن، و«اللغة»، و«اختصارات لوحة المفاتيح» (أو اضغط ?).',
  'demo.tour.area.start': 'ابدأ من هنا',
