  'demo.tour.overview.title': 'Curahold في دقيقتين',
  'demo.tour.overview.blurb': 'الصفحة الرئيسية وعملاؤك وحمل الفريق وCuraAI — الجولة التي تبدأ بها.',
  'demo.tour.overview.1.title': 'هذا هو المنتج الحقيقي',
  'demo.tour.overview.1.body': 'ليس تسجيلًا: يعمل Curahold في هذا التبويب، مع شركة متخيَّلة وعملائها. أنت سارة المنصوري، تقودين نجاح العملاء هناك. انقر حيث شئت في أي وقت، والجولة تنتظرك.',
  'demo.tour.overview.2.title': 'صفحة رئيسية لكل دور',
  'demo.tour.overview.2.body': '«يومي» للفريق، و«عرض الفريق» للقادة، و«ملخص الإدارة» للإدارة العليا. كل صفحة بطاقات يمكنك نقلها وإضافتها وحذفها من «تعديل الصفحة».',
  'demo.tour.overview.3.title': 'من يحمل ماذا',
  'demo.tour.overview.3.body': 'العملاء والعمل المفتوح والمهام المتأخرة لكل شخص، فيرى القائد من يتحمل فوق طاقته قبل أن يقولها أحد. انقر اسمًا لترى أسبوع صاحبه.',
  'demo.tour.overview.4.title': 'العملاء الذين يحتاجونك أولًا',
  'demo.tour.overview.4.body': 'كل عميل بطاقة، مرتبة حسب حاجته إلى الاهتمام، والبطاقة تقول السبب: درجة منخفضة، أو عمل متأخر، أو تجديد يقترب.',
  'demo.tour.overview.5.title': 'اسأل عن أي شيء، من أي مكان',
  'demo.tour.overview.5.body': 'يجيب CuraAI عن أسئلة مساحة عملك والمنتج، مع مصدر كل إجابة. وهو موجود في كل شاشة.',
  'demo.tour.health.title': 'اعرف لماذا يتعرض عميل للخطر',
