  'fin.what.parasut': "العملاء وفواتير المبيعات والمدفوعات من Paraşüt.",
  'fin.what.quickbooks': "العملاء والفواتير والمدفوعات من QuickBooks Online.",
  'fin.what.finfile': "Logo أو Mikro أو Tally أو SAP Business One أو أي برنامج آخر: ارفع ملف تصدير Excel أو CSV.",
  'fin.steps.zohobooks': "سجّل الدخول بحساب Zoho الذي يرى مؤسستك في Zoho Books.\nاسمح لـ Curahold بقراءة جهات الاتصال والفواتير والمدفوعات. يطلب صلاحية القراءة فقط.\nبعد العودة إلى هنا، ابدأ القراءة الأولى وراجع العملاء الذين تعذّرت مطابقتهم.",
  'fin.steps.xero': "سجّل الدخول إلى Xero واختر المؤسسة التي تريد ربطها.\nاسمح بصلاحية قراءة جهات الاتصال والمعاملات؛ لا يستطيع Curahold تغيير أي شيء في Xero.\nبعد العودة إلى هنا، ابدأ القراءة الأولى وراجع العملاء الذين تعذّرت مطابقتهم.",
  'fin.steps.freee': "سجّل الدخول إلى freee واختر الشركة (事業所) التي تريد ربطها.\nاسمح بالوصول؛ يقرأ Curahold الشركاء وصفقات المبيعات فقط.\nبعد العودة إلى هنا، ابدأ القراءة الأولى وراجع العملاء الذين تعذّرت مطابقتهم.",
  'fin.steps.quickbooks': "سجّل الدخول إلى Intuit واختر شركة QuickBooks التي تريد ربطها.\nاسمح بالوصول إلى بيانات المحاسبة؛ يقرأ Curahold العملاء والفواتير والمدفوعات فقط.\nبعد العودة إلى هنا، ابدأ القراءة الأولى وراجع العملاء الذين تعذّرت مطابقتهم.",
  'fin.steps.odoo': "في Odoo، افتح ملفك الشخصي ← التفضيلات ← أمان الحساب وأنشئ مفتاح API.\nدوّن عنوان Odoo واسم الدخول. وعلى Odoo.sh أو خادمك الخاص، اسم قاعدة البيانات أيضًا.\nأدخلها أدناه. على Odoo Online، يتطلب الوصول إلى API خطة Custom (قاعدة Odoo).",
  'fin.steps.parasut': "اطلب من دعم Paraşüt صلاحية API لشركتك؛ سيرسلون معرّف العميل وسرّه.\nرقم شركتك في شريط العنوان بعد uygulama.parasut.com/.\nأدخلها مع البريد الإلكتروني وكلمة المرور لمستخدم في Paraşüt. تُستخدم كلمة المرور مرة واحدة للحصول على مفتاح ولا تُحفظ.",
  'fin.steps.finfile': "صدّر العملاء والفواتير والمدفوعات من برنامجك بصيغة Excel أو CSV.\nضعها في أعمدة القالب؛ يمكنك تنزيل القالب في الشاشة التالية.\nارفع العملاء أولًا، ثم الفواتير، ثم المدفوعات. ارفع ملفًا جديدًا متى أردت أرقامًا أحدث.",
